package com.railway.dao;
import com.railway.model.Train;import java.sql.*;import java.time.LocalDate;import java.util.*;
public class TrainDao {
 public List<Train> search(String src,String dst,LocalDate date)throws SQLException{List<Train> out=new ArrayList<>();String sql="SELECT t.id,t.train_number,t.train_name,t.source,t.destination,t.departure_time,t.arrival_time,t.fare,s.available_seats FROM trains t JOIN train_schedules s ON s.train_id=t.id WHERE t.active=1 AND LOWER(t.source)=LOWER(?) AND LOWER(t.destination)=LOWER(?) AND s.journey_date=? ORDER BY t.departure_time";try(Connection c=com.railway.util.DB.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,src.trim());p.setString(2,dst.trim());p.setDate(3,java.sql.Date.valueOf(date));try(ResultSet r=p.executeQuery()){while(r.next()){Train t=new Train();t.setId(r.getLong("id"));t.setNumber(r.getString("train_number"));t.setName(r.getString("train_name"));t.setSource(r.getString("source"));t.setDestination(r.getString("destination"));t.setDeparture(r.getTime("departure_time"));t.setArrival(r.getTime("arrival_time"));t.setFare(r.getBigDecimal("fare"));t.setAvailableSeats(r.getInt("available_seats"));out.add(t);}}}return out;}
 public void add(String number,String name,String src,String dst,Time dep,Time arr,java.math.BigDecimal fare,int cap)throws SQLException{try(Connection c=com.railway.util.DB.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO trains(train_number,train_name,source,destination,departure_time,arrival_time,fare,capacity) VALUES(?,?,?,?,?,?,?,?)")){p.setString(1,number);p.setString(2,name);p.setString(3,src);p.setString(4,dst);p.setTime(5,dep);p.setTime(6,arr);p.setBigDecimal(7,fare);p.setInt(8,cap);p.executeUpdate();}}
}
